namespace SpinalShatter;

[Tool]
public partial class Door : CharacterBody3D
{
	[Signal] public delegate void DoorOpenEventHandler(Door door);
	[Signal] public delegate void PlayerDoorShutEventHandler();
	[Signal] public delegate void SystemDoorShutEventHandler();
	[Export] public CardinalDirection DoorDirection { get; set; }

	[ExportGroup("Components")]
	[Export] private AnimationPlayer animator;
	[Export] private Area3D entrance;
	[Export] private Area3D exit;

	private bool _isSystemClose = false;

	[ExportGroup("")]
	private bool isOpen = true;
	[Export] public bool IsOpen
	{
		get => isOpen;
		private set
		{
			bool was = isOpen;
			isOpen = value;
			if (!this.IsInsideTree()) return;
#if TOOLS
			if (Engine.IsEditorHint()) GetComponents();
#endif
			switch (was)
			{
				case false when isOpen:
					PlayerOpen();
					break;
				case true when !isOpen:
					PlayerClose();
					break;
			}
		}
	}

	[Export] public bool Locked { get; set; }

	private bool partOfHub;

	public override void _Ready()
	{
		GetComponents();
		if (!this.IsInGame()) return;

		partOfHub = IsInGroup("Hub");
	}

	public override void _EnterTree()
	{
		base._EnterTree();
		TrySubscribe();
		IsOpen = isOpen;
	}

	public override void _ExitTree()
	{
		base._ExitTree();
		TryUnsubscribe();
	}

	private void GetComponents()
	{
		animator ??= GetNode<AnimationPlayer>("AnimationPlayer");
		entrance ??= GetNode<Area3D>("EntranceArea");
		exit ??= GetNode<Area3D>("ExitArea");
	}

	private void OnExitAreaBodyExited(Node3D body)
	{
		if (body is PlayerBody player && !entrance.GetOverlappingBodies().Contains(player))
		{
			// Allow closing if it's a level door, OR if it's a hub door during the post-round state.
			if (!partOfHub ||
				(partOfHub && !WaveDirector.Instance.IsRoundStarted && WaveDirector.Instance.IsRoundCompleted))
			{
				PlayerClose();
			}
		}
	}

	private void PlayerOpen()
	{
		if (isOpen) return;
		// DebugManager.Debug($"Door '{Name}' PlayerOpen() called. Locked: {Locked}");
		if (Locked) return;
		animator.Play("OpenDown");
	}

	public void SystemOpen()
	{
		if (isOpen) return;
		// DebugManager.Debug($"Door '{Name}' ForceOpen() called.");
		Locked = false;
		animator.Play("OpenDown");
	}

	private void PlayerClose()
	{
		if (!isOpen) return;
		// DebugManager.Debug($"Door '{Name}' PlayerClose() called. Locked: {Locked}");
		if (Locked) return;
		_isSystemClose = false;
		animator.Play("CloseUp");
		if (this.IsInGame()) Locked = true;
	}

	public void SystemClose()
	{
		if (!isOpen) return;
		// DebugManager.Debug($"Door '{Name}' ForceClose() called.");
		_isSystemClose = true;
		animator.Play("CloseUp");
		if (this.IsInGame()) Locked = true;
	}

	public void InstantOpen()
	{
		animator.Play("Opened");
		isOpen = true;
	}

	public void InstantClose()
	{
		animator.Play("Closed");
		isOpen =  false;
	}

	private void OnAnimationFinished(StringName animation)
	{
		if (animation == "OpenDown")
		{
			InstantOpen();
			EmitSignalDoorOpen(this);
		}
		else if (animation == "CloseUp")
		{
			InstantClose();
			EmitSignal(_isSystemClose ? SignalName.SystemDoorShut : SignalName.PlayerDoorShut);
		}
	}

	private void TrySubscribe()
	{
		if (Engine.IsEditorHint()) return;
		animator.SafeSubscribe<StringName>(AnimationPlayer.SignalName.AnimationFinished, OnAnimationFinished);
		exit?.SafeSubscribe<Node3D>(Area3D.SignalName.BodyExited, OnExitAreaBodyExited);
	}

	private void TryUnsubscribe()
	{
		if (Engine.IsEditorHint()) return;
		animator.SafeUnsubscribe<StringName>(AnimationPlayer.SignalName.AnimationFinished, OnAnimationFinished);
		exit?.SafeUnsubscribe<Node3D>(Area3D.SignalName.BodyExited, OnExitAreaBodyExited);
	}
}

using Godot;
using Godot.Collections;
using System.Collections.Generic;
using System.Linq;
using Elythia;

namespace SpinalShatter;

public partial class LevelRoom : Node3D
{
	[Signal]
	public delegate void PlayerEnteredEventHandler(LevelRoom room);

	[Signal]
	public delegate void PlayerExitedEventHandler(LevelRoom room);

	[Signal]
	public delegate void WaveClearedEventHandler();

	[Export] public CardinalDirection RoomDirection { get; set; }
	[Export] private bool alwaysShow = false;
	public bool IsCentralHub { get; set; } = false;

	private Array<EnemySpawner> _spawners;
	private Area3D _triggerVolume;
	private Door levelDoor;

	private bool _spawningFinished = false;

	public bool IsActive { get; private set; }
	public List<Enemy> EnemiesInRoom { get; private set; } = new();
	public int EnemyCount => EnemiesInRoom.Count;

	public Door LevelDoor => levelDoor;

	public override void _Ready()
	{
		// Self-register with WaveDirector if this is a combat room
		IsCentralHub = IsInGroup("Hub");
		if (!IsCentralHub)
		{
			levelDoor = GetNode<Door>("Door");
			levelDoor.PlayerDoorShut += OnLevelDoorShut;
		}

		// Common logic for all rooms below
		_triggerVolume = GetNode<Area3D>("%LevelRegion");
		if (_triggerVolume != null)
		{
			_triggerVolume.BodyEntered += OnBodyEntered;
			_triggerVolume.BodyExited += OnBodyExited;
		}

		var spawnerRoot = GetNode<Node3D>("%Spawners");

		_spawners ??= new Array<EnemySpawner>();
		foreach (var child in spawnerRoot.GetChildren())
		{
			if (child is EnemySpawner spawner)
			{
				_spawners.Add(spawner);
			}
		}

		foreach (var spawner in _spawners)
		{
			spawner.SpawningFinished += OnSpawningFinished;
		}

		// Find any enemies that are pre-placed in the room in the editor
		FindEnemiesRecursively(this);

		RoomManager.Instance.RegisterRoom(this);
	}

	public void StartSpawning(Array<PackedScene> enemies)
	{
		if (_spawners.Count == 0)
		{
			GD.PrintErr($"LevelRoom '{Name}' has no spawners, cannot start spawning.");
			return;
		}

		_spawningFinished = false;

		// Initialize pools for all unique scenes on all potential spawners
		var uniqueScenes = enemies.Distinct();
		foreach (var spawner in _spawners)
		{
			spawner.InitializePools(uniqueScenes);
		}

		// Pick a single random spawner to handle the whole wave
		var chosenSpawner = _spawners[(int)(GD.Randi() % _spawners.Count)];
		chosenSpawner.StartSpawningWave(enemies);
	}

	private void OnSpawningFinished()
	{
		_spawningFinished = true;
		CheckWaveCleared();
	}

	private void OnLevelDoorShut()
	{
		if (WaveDirector.Instance.IsRoundStarted) return;
		WaveDirector.Instance.StartRound(this);
	}

	private void OnEnemyDied(Enemy who)
	{
		// DebugManager.Debug($"LevelRoom: {Name} OnEnemyDied called for {who.Name}.");
		UnregisterEnemy(who);
	}

	private void CheckWaveCleared()
	{
		if (!IsActive || !_spawningFinished)
		{
			return;
		}

		// If spawning is finished and no enemies are left, the wave is cleared
		if (EnemiesInRoom.Count == 0)
		{
			EmitSignalWaveCleared();
			GD.Print("Wave Cleared!");
		}
	}

	private void FindEnemiesRecursively(Node node)
	{
		foreach (var child in node.GetChildren())
		{
			if (child is Enemy enemy)
			{
				RegisterEnemy(enemy);
			}
			else
			{
				FindEnemiesRecursively(child);
			}
		}
	}

	public void RegisterEnemy(Enemy enemy)
	{
		if (EnemiesInRoom.Contains(enemy)) return;
		EnemiesInRoom.Add(enemy);
		enemy.AssociatedRoom = this;
		enemy.EnemyDied += OnEnemyDied;

		// DebugManager.Debug($"LevelRoom: {Name} Registered enemy {enemy.Name}. Total enemies: {_enemiesInRoom.Count}");
	}

	public void UnregisterEnemy(Enemy enemy)
	{
		if (EnemiesInRoom.Remove(enemy))
		{
			enemy.EnemyDied -= OnEnemyDied;

			// DebugManager.Debug($"LevelRoom: {Name} Unregistered enemy {enemy.Name}. Total enemies: {_enemiesInRoom.Count}");
			CheckWaveCleared();
		}
	}

	private void OnBodyEntered(Node3D body)
	{
		//DebugManager.Trace($"{body.Name} entered {this.Name}");
		if (body is PlayerBody)
		{
			RoomManager.Instance.RegisterRoom(this);

			Activate();
			EmitSignalPlayerEntered(this);
		}
		else if (body is Enemy enemy && enemy.AssociatedRoom != this)
		{
			enemy.AssociatedRoom?.UnregisterEnemy(enemy);
			RegisterEnemy(enemy);
		}
	}

	private void OnBodyExited(Node3D body)
	{
		//DebugManager.Trace($"{body.Name} entered {this.Name}");
		if (body is PlayerBody)
		{
			EmitSignalPlayerExited(this);
			Deactivate();
		}
	}


	public void OnRoundCompletion()
	{
		if (levelDoor != null)
		{
			levelDoor.SystemOpen();
		}
	}

	public void Activate()
	{
		IsActive = true;
		ShowRoom();

		// Pre-placed enemies are activated here
		foreach (var enemy in EnemiesInRoom)
		{
			enemy.Activate();
		}
	}

	public void Deactivate()

	{
		IsActive = false;

		if (!alwaysShow) HideRoom();


		// Deactivate any remaining enemies

		foreach (var enemy in EnemiesInRoom)

		{
			enemy.Deactivate();
		}
	}

	public void ShowRoom()
	{
		Visible = true;
	}

	public void HideRoom()
	{
		Visible = alwaysShow;
	}
}

